    var r = ROUTES[e.air], d = e.progress, i, n = r.p.length;
    if (d >= r.len) { e.x = r.p[n - 1][0]; e.y = r.p[n - 1][1]; return; }
    for (i = 1; i < n; i++) {
      if (d <= r.cum[i]) {
        var a = r.p[i - 1], b = r.p[i], o = d - r.cum[i - 1];
        e.x = a[0] + (b[0] > a[0] ? o : b[0] < a[0] ? -o : 0);
        e.y = a[1] + (b[1] > a[1] ? o : b[1] < a[1] ? -o : 0);
        return;
      }
    }
  }
  var mult = [0, 1000];
  function mOf(w) { while (mult.length <= w) mult.push(Math.floor(mult[mult.length - 1] * 108 / 100)); return mult[w]; }
  var rng = mulberry32(seed);
  function genWave(w) {
    var n = 4 + Math.floor(3 * w / 5), out = [], av = [], total = 0, i, j;
    for (i = 0; i < ORDER.length; i++) if (ET[ORDER[i]].first <= w) { av.push(ORDER[i]); total += ET[ORDER[i]].weight; }
    for (i = 0; i < n; i++) {
      var r = rng() % total;
      for (j = 0; j < av.length; j++) {
        var wt = ET[av[j]].weight;
        if (r < wt) { out.push(av[j]); break; }
        r -= wt;
      }
    }
    return out;
  }
  function view(e) {
    return { id: e.id, type: e.type, hp: e.hp, maxHp: e.maxHp, x: e.x, y: e.y, air: e.air, armor: e.armor,
      speed: e.speed, slowed: e.slow, remaining: e.len - e.progress };
  }
  function tDamage(t) {
    var d = TT[t.type].dmg, k;
    for (k = 1; k < t.tier; k++) d = Math.floor(d * 16 / 10);
    return d;
  }
  var strat = createStrategy();
