      for (k = 0; k < enemies.length; k++) st.enemies.push(view(enemies[k]));
      var acts = strat.plan(st);
      if (acts && typeof acts.length === 'number') {
        var na = Math.min(32, acts.length);
        for (k = 0; k < na; k++) {
          var a = acts[k];
          if (!a || typeof a !== 'object') continue;
          var sl = a.slot;
          if (typeof sl !== 'number' || sl !== Math.floor(sl) || sl < 0 || sl > 15) continue;
          var cur = turrets[sl];
          if (a.op === 'build') {
            if (cur || typeof a.type !== 'string' || !TT.hasOwnProperty(a.type)) continue;
            var c = TT[a.type].cost;
            if (gold < c) continue;
            gold -= c;
            turrets[sl] = { slot: sl, type: a.type, tier: 1, spent: c, cd: 0, x: SLOTS[sl][0] * 100 + 50, y: SLOTS[sl][1] * 100 + 50 };
            log.push([tick, 'B', sl, TT[a.type].i]);
            if (hook) hook('B', tick, sl, a.type);
          } else if (a.op === 'upgrade') {
            if (!cur || cur.tier >= 3) continue;
            var uc = TT[cur.type].cost * cur.tier;
            if (gold < uc) continue;
            gold -= uc; cur.tier++; cur.spent += uc;
            log.push([tick, 'U', sl, cur.tier]);
            if (hook) hook('U', tick, sl, cur.tier);
