      log.push([tick, 'F', wave, 0]);
      fallTick = tick;
      compact();
      if (hook) hook('F', tick, wave);
      break;
    }
    if (anyDead) compact();
    // 4. age & heal
    for (k = 0; k < enemies.length; k++) {
      e = enemies[k];
      e.age++;
      if (e.type === 'mender' && e.age % 20 === 0) {
        for (var j = 0; j < enemies.length; j++) {
          var o = enemies[j], dx = o.x - e.x, dy = o.y - e.y;
