      if (!t) continue;
      if (t.cd > 0) { t.cd--; if (t.cd > 0) continue; }
      var T = TT[t.type], range = T.range + 30 * (t.tier - 1), r2 = range * range, cands = [];
      for (k = 0; k < enemies.length; k++) {
        e = enemies[k];
