      if (typeof strat.target === 'function') {
        var views = [];
        for (k = 0; k < cands.length; k++) views.push(view(cands[k]));
        var pick = strat.target({ slot: s, type: t.type, tier: t.tier, x: t.x, y: t.y, range: range }, views);
        if (typeof pick === 'number') for (k = 0; k < cands.length; k++) if (cands[k].id === pick) { tgt = cands[k]; break; }
      }
      var dmg = tDamage(t), hits = [];
      if (T.splash > 0) {
        var s2 = T.splash * T.splash;
        for (k = 0; k < enemies.length; k++) {
          e = enemies[k];
          if (e.dead || !(e.air ? T.a : T.g)) continue;
          var sx = e.x - tgt.x, sy = e.y - tgt.y;
          if (sx * sx + sy * sy <= s2) hits.push(e);
