        e = hits[k];
        e.hp -= T.pierce ? dmg : Math.max(1, dmg - e.armor);
        if (T.slow > 0) e.slow = T.slow;
      }
      t.cd = T.period;
      if (hook) hook('X', tick, t, tgt, hits);
      var killed = false;
