            turrets[sl] = { slot: sl, type: a.type, tier: 1, spent: c, cd: 0, x: SLOTS[sl][0] * 100 + 50, y: SLOTS[sl][1] * 100 + 50 };
            log.push([tick, 'B', sl, TT[a.type].i]);
            if (hook) hook('B', tick, sl, a.type);
          } else if (a.op === 'upgrade') {
            if (!cur || cur.tier >= 3) continue;
            var uc = TT[cur.type].cost * cur.tier;
            if (gold < uc) continue;
            gold -= uc; cur.tier++; cur.spent += uc;
            log.push([tick, 'U', sl, cur.tier]);
            if (hook) hook('U', tick, sl, cur.tier);
          } else if (a.op === 'sell') {
            if (!cur) continue;
            gold += Math.floor(cur.spent * 70 / 100);
            turrets[sl] = null;
            log.push([tick, 'S', sl, 0]);
            if (hook) hook('S', tick, sl, cur.type);
          }
        }
      }
      var wl = waves[wave];
      for (k = 0; k < wl.length; k++) queue.push({ tick: tick + 4 * k, wave: wave, idx: k, type: wl[k] });
      queue.sort(function (p, q) { return p.tick - q.tick || p.wave - q.wave || p.idx - q.idx; });
      delete waves[wave];
      if (hook) hook('W', tick, wave);
    }
    // 2. spawn
    while (queue.length && queue[0].tick <= tick) {
      var q0 = queue.shift();
      mkEnemy(q0.type, q0.wave, Math.floor(ET[q0.type].hp * mOf(q0.wave) / 1000), 0);
    }
    // 3. move
    var fell = false, anyDead = false;
    for (k = 0; k < enemies.length; k++) {
      e = enemies[k];
      e.progress += e.slow > 0 ? Math.floor(e.speed * 60 / 100) : e.speed;
      if (e.progress >= e.len) {
        baseHp -= e.leak; e.dead = true; anyDead = true;
        log.push([tick, 'L', e.id, baseHp]);
        if (hook) hook('L', tick, e, baseHp);
        if (baseHp <= 0) { fell = true; break; }
      } else place(e);
    }
    if (fell) {
      log.push([tick, 'F', wave, 0]);
      fallTick = tick;
      compact();
      if (hook) hook('F', tick, wave);
      break;
    }
    if (anyDead) compact();
    // 4. age & heal
    for (k = 0; k < enemies.length; k++) {
      e = enemies[k];
      e.age++;
      if (e.type === 'mender' && e.age % 20 === 0) {
        for (var j = 0; j < enemies.length; j++) {
          var o = enemies[j], dx = o.x - e.x, dy = o.y - e.y;
          if (dx * dx + dy * dy <= 22500) { o.hp += Math.floor(o.maxHp * 8 / 100); if (o.hp > o.maxHp) o.hp = o.maxHp; }
        }
        if (hook) hook('H', tick, e);
      }
    }
    // 5. turrets
    for (s = 0; s < 16; s++) {
      var t = turrets[s];
      if (!t) continue;
      if (t.cd > 0) { t.cd--; if (t.cd > 0) continue; }
      var T = TT[t.type], range = T.range + 30 * (t.tier - 1), r2 = range * range, cands = [];
      for (k = 0; k < enemies.length; k++) {
        e = enemies[k];
        if (e.dead || !(e.air ? T.a : T.g)) continue;
        var ddx = e.x - t.x, ddy = e.y - t.y;
        if (ddx * ddx + ddy * ddy <= r2) cands.push(e);
      }
      if (!cands.length) continue;
      var tgt = cands[0];
      for (k = 1; k < cands.length; k++) if (cands[k].len - cands[k].progress < tgt.len - tgt.progress) tgt = cands[k];
      if (typeof strat.target === 'function') {
        var views = [];
        for (k = 0; k < cands.length; k++) views.push(view(cands[k]));
        var pick = strat.target({ slot: s, type: t.type, tier: t.tier, x: t.x, y: t.y, range: range }, views);
        if (typeof pick === 'number') for (k = 0; k < cands.length; k++) if (cands[k].id === pick) { tgt = cands[k]; break; }
      }
      var dmg = tDamage(t), hits = [];
      if (T.splash > 0) {
        var s2 = T.splash * T.splash;
        for (k = 0; k < enemies.length; k++) {
          e = enemies[k];
          if (e.dead || !(e.air ? T.a : T.g)) continue;
          var sx = e.x - tgt.x, sy = e.y - tgt.y;
          if (sx * sx + sy * sy <= s2) hits.push(e);
        }
      } else hits.push(tgt);
      for (k = 0; k < hits.length; k++) {
        e = hits[k];
        e.hp -= T.pierce ? dmg : Math.max(1, dmg - e.armor);
        if (T.slow > 0) e.slow = T.slow;
      }
      t.cd = T.period;
      if (hook) hook('X', tick, t, tgt, hits);
      var killed = false;
      for (k = 0; k < hits.length; k++) {
        e = hits[k];
        if (e.hp <= 0) {
          e.dead = true; killed = true;
          gold += e.bounty;
          log.push([tick, 'K', e.id, s]);
          if (hook) hook('K', tick, e, s);
          if (e.type === 'splitter') {
            var mh = Math.max(1, Math.floor(e.maxHp / 4));
            for (var c3 = 0; c3 < 3; c3++) mkEnemy('splitling', e.wave, mh, e.progress);
          }
        }
      }
      if (killed) compact();
    }
    // 6. slow timers
    for (k = 0; k < enemies.length; k++) if (enemies[k].slow > 0) enemies[k].slow--;
    if (hook) hook('T', tick, { gold: gold, baseHp: baseHp, wave: wave, enemies: enemies, turrets: turrets, nextWave: waves[wave + 1] || [] });
  }
  var endTick = fallTick >= 0 ? fallTick : maxTicks;
  var str = JSON.stringify(log), h = 0x811c9dc5;
  for (i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193); }
  return { score: Math.round((endTick - 20) / 40 * 100) / 100, fallTick: fallTick,
    log: log, hash: ('00000000' + (h >>> 0).toString(16)).slice(-8) };
}

