var leakBy = {}, tot = 0;
for (var sd = 200; sd < 230; sd++) {
  var lastGold = 0, full = -1, firstLeak = -1, lk = [];
  var r = rampartSimulate(createStrategy, sd, 12020, function (k, tick, a, b) {
    if (k === 'L') { leakBy[a.type] = (leakBy[a.type] || 0) + a.leak; if (firstLeak < 0) firstLeak = tick; lk.push(a.type[0] + ((tick - 20) / 40 | 0)); }
    if (k === 'T') { lastGold = a.gold; if (full < 0 && a.turrets.every(function (t) { return t && t.tier === 3; })) full = tick; }
  });
  tot += r.score;
  print(sd, r.score, 'gold', lastGold, 'fullAtWave', full < 0 ? -1 : ((full - 20) / 40).toFixed(1), 'leaks', lk.join(' '));
}
print(tot / 30, JSON.stringify(leakBy));

