function createStrategy() {
  var P = /*PARAMS*/PARAMS/*END*/;
  var TYPES = P.types, ORDER = P.order;
  var COST = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
  var DMG = { bolt: [26, 41, 65], cannon: [60, 96, 153], frost: [10, 16, 25], lance: [180, 288, 460], flak: [40, 64, 102] };
  var SPD = { grunt: 10, runner: 20, wisp: 12, brute: 6, splitter: 8, mender: 8, splitling: 12 };
  var done = [], curWave = ['grunt', 'grunt', 'grunt', 'grunt'], mult = [0, 1000], i0;
  for (i0 = 0; i0 < ORDER.length; i0++) done.push(false);
  function mOf(w) { while (mult.length <= w) mult.push(Math.floor(mult[mult.length - 1] * 108 / 100)); return mult[w]; }
  function plan(s) {
    var acts = [], gold = s.gold, tiers = [], i, w = s.wave, e;
    for (i = 0; i < 16; i++) tiers.push(s.slots[i].turret ? s.slots[i].turret.tier : 0);
    // reserve (interest banking) unless something is getting close to the keep
    var res = w >= P.resEnd ? 0 : Math.min(P.resMax, P.resSlope * w);
    var airHp = 0;
    for (i = 0; i < s.enemies.length; i++) {
      e = s.enemies[i];
      if (e.air) { airHp += e.hp; if (e.remaining < P.dangerRem * 0.565) res = 0; }
      else if (e.remaining < P.dangerRem) res = 0;
    }
    var nw = 0, nn = 0;
    for (i = 0; i < curWave.length; i++) if (curWave[i] === 'wisp') nw++;
    for (i = 0; i < s.nextWave.length; i++) if (s.nextWave[i] === 'wisp') nn++;
    airHp += nw * Math.floor(50 * mOf(w) / 1000) + nn * Math.floor(50 * mOf(w + 1) / 1000);
    var guard = 0;
    while (acts.length < 32 && guard++ < 100) {
      var airCap = 0;
      for (i = 0; i < 16; i++) if (tiers[i] > 0) {
        var ty0 = TYPES[i];
        if (ty0 === 'flak') airCap += DMG.flak[tiers[i] - 1] / 10; else if (ty0 === 'bolt') airCap += DMG.bolt[tiers[i] - 1] / 16;
      }
      var needAir = airHp > P.airK * airCap, pick = -1, first = -1;
      for (i = 0; i < ORDER.length; i++) {
        if (done[i]) continue;
        if (tiers[ORDER[i]] >= 3) { done[i] = true; continue; }
        if (first < 0) first = i;
        if (!needAir) break;
        if (TYPES[ORDER[i]] === 'flak') { pick = i; break; }
      }
      if (pick < 0) pick = first;
      if (pick < 0) break;
      var sl = ORDER[pick], ty = TYPES[sl], t = tiers[sl];
      var c = t === 0 ? COST[ty] : COST[ty] * t;
      if (gold - c < res) break;
      gold -= c; tiers[sl] = t + 1; done[pick] = true;
      acts.push(t === 0 ? { op: 'build', slot: sl, type: ty } : { op: 'upgrade', slot: sl });
    }
    curWave = s.nextWave.slice();
    return acts;
  }
  function target(tu, c) {
    var n = c.length;
    if (n === 1) return c[0].id;
    var d = DMG[tu.type][tu.tier - 1], best = -1, bs = -1e18, i, j, e, sc, URG = P.urg;
    if (tu.type === 'cannon' || tu.type === 'flak') {
      var r2 = tu.type === 'cannon' ? 8100 : 4900, val = [];
      for (j = 0; j < n; j++) {
        var o = c[j], ef = d - o.armor; if (ef < 1) ef = 1;
        var v = ef < o.hp ? ef : o.hp + P.killB * ef;
        if (o.type === 'mender') v *= P.mendW; else if (o.type === 'runner') v *= P.runW;
        if (o.remaining * 10 < URG * SPD[o.type]) v *= P.urgW;
        val.push(v);
      }
      for (i = 0; i < n; i++) {
        e = c[i]; sc = 0;
        for (j = 0; j < n; j++) {
          var dx = c[j].x - e.x, dy = c[j].y - e.y;
          if (dx * dx + dy * dy <= r2) sc += val[j];
        }
        sc = sc * 10000 - e.remaining;
        if (sc > bs) { bs = sc; best = e.id; }
      }
      return best;
    }
    if (tu.type === 'frost') {
      for (i = 0; i < n; i++) {
        e = c[i];
        sc = (e.slowed > P.frostTh ? 0 : 1e7) - e.remaining + (e.type === 'runner' ? P.frostRun : 0) + (e.type === 'splitling' ? -P.frostSpl : 0);
        if (sc > bs) { bs = sc; best = e.id; }
      }
      return best;
    }
    for (i = 0; i < n; i++) {
      e = c[i];
      var ef2 = tu.type === 'lance' ? d : (d - e.armor < 1 ? 1 : d - e.armor);
      var v2 = ef2 < e.hp ? ef2 : e.hp + P.killB * ef2;
      if (tu.type === 'lance') v2 += e.armor * P.lanceArm;
      if (e.type === 'mender') v2 *= P.mendW; else if (e.type === 'runner') v2 *= P.runW;
      if (tu.type === 'bolt' && e.air) v2 *= P.boltAir;
      if (e.remaining * 10 < URG * SPD[e.type]) v2 *= P.urgW;
      sc = v2 * 10000 - e.remaining;
      if (sc > bs) { bs = sc; best = e.id; }
    }
    return best;
  }
  return { plan: plan, target: target };
}

