function createStrategy() {
  var P = (typeof PARAMS !== 'undefined') ? PARAMS : null;
  var TYPES = P.types, ORDER = P.order, RES = P.reserve || 0, URG = P.urg || 600;
  var COST = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
  var DMG = { bolt: [26, 41, 65], cannon: [60, 96, 153], frost: [10, 16, 25], lance: [180, 288, 460], flak: [40, 64, 102] };
  var ptr = 0;
  function plan(s) {
    var acts = [], gold = s.gold, tiers = [], i;
    for (i = 0; i < 16; i++) tiers.push(s.slots[i].turret ? s.slots[i].turret.tier : 0);
    while (ptr < ORDER.length && acts.length < 32) {
      var sl = ORDER[ptr], ty = TYPES[sl], t = tiers[sl];
      if (t >= 3) { ptr++; continue; }
      var c = t === 0 ? COST[ty] : COST[ty] * t;
      if (gold - c < (ptr >= ORDER.length - 1 ? 0 : RES)) break;
      gold -= c; tiers[sl] = t + 1; ptr++;
      acts.push(t === 0 ? { op: 'build', slot: sl, type: ty } : { op: 'upgrade', slot: sl });
    }
    return acts;
  }
  function target(tu, c) {
    var n = c.length;
    if (n === 1) return c[0].id;
    var d = DMG[tu.type][tu.tier - 1], best = -1, bs = -1e18, i, j, e, sc;
    if (tu.type === 'cannon' || tu.type === 'flak') {
      var r2 = tu.type === 'cannon' ? 8100 : 4900;
      for (i = 0; i < n; i++) {
        e = c[i]; sc = 0;
        for (j = 0; j < n; j++) {
          var o = c[j], dx = o.x - e.x, dy = o.y - e.y;
          if (dx * dx + dy * dy <= r2) {
            var ef = d - o.armor; if (ef < 1) ef = 1;
            var v = ef < o.hp ? ef : o.hp + P.killB * ef;
            if (o.type === 'mender') v *= P.mendW;
            if (o.remaining < URG) v *= P.urgW;
            sc += v;
          }
        }
        sc = sc * 10000 - e.remaining;
        if (sc > bs) { bs = sc; best = e.id; }
      }
      return best;
    }
    if (tu.type === 'frost') {
      for (i = 0; i < n; i++) {
        e = c[i];
        sc = (e.slowed > P.frostTh ? 0 : 1e7) - e.remaining + (e.type === 'runner' ? P.frostRun : 0) + (e.type==='splitling'? -P.frostSpl:0);
        if (sc > bs) { bs = sc; best = e.id; }
      }
      return best;
    }
    for (i = 0; i < n; i++) {
      e = c[i];
      var ef2 = tu.type === 'lance' ? d : (d - e.armor < 1 ? 1 : d - e.armor);
      var v2 = ef2 < e.hp ? ef2 : e.hp + P.killB * ef2;
      if (tu.type === 'lance') v2 += e.armor * P.lanceArm;
      if (e.type === 'mender') v2 *= P.mendW;
      if (tu.type === 'bolt' && e.air) v2 *= P.boltAir;
      if (e.remaining < URG) v2 *= P.urgW;
      sc = v2 * 10000 - e.remaining;
      if (sc > bs) { bs = sc; best = e.id; }
    }
    return best;
  }
  return { plan: plan, target: P.noTarget ? undefined : target };
}

