// usage: jsc verify.js -- <path to index.html>
var html = readFile(arguments[0]);
function grab(id) { var m = html.match(new RegExp('<script id="' + id + '">([\\s\\S]*?)</script>')); if (!m) throw new Error('missing ' + id); return m[1]; }
var before = Object.getOwnPropertyNames(this).length;
(0, eval)(grab('rampart-strategy'));
(0, eval)(grab('rampart-sim'));
print('globals: createStrategy', typeof createStrategy, 'rampartSimulate', typeof rampartSimulate, 'len', rampartSimulate.length);
var A = function () { return { plan: function (s) { var a = [], g = s.gold; for (var i = 0; i < s.slots.length; i++) { var sl = s.slots[i]; if (!sl.turret && g >= 50) { a.push({ op: 'build', slot: sl.slot, type: 'bolt' }); g -= 50; } } return a; } }; };
var r = rampartSimulate(A, 42, 12020); print('A', r.score, r.fallTick, r.log.length, r.hash, r.hash === '82a5353d');
var B = function () { return { plan: function (s) { if (s.wave === 1) return [{ op: 'build', slot: 3, type: 'cannon' }, { op: 'build', slot: 6, type: 'frost' }]; if (s.wave === 3) return [{ op: 'upgrade', slot: 3 }, { op: 'build', slot: 12, type: 'flak' }]; if (s.wave === 6) return [{ op: 'build', slot: 8, type: 'lance' }, { op: 'sell', slot: 6 }]; return []; } }; };
r = rampartSimulate(B, 7, 12020); print('B', r.score, r.fallTick, r.log.length, r.hash, r.hash === '2e8858d7');
var r1 = rampartSimulate(createStrategy, 42, 2020), r2 = rampartSimulate(createStrategy, 42, 2020), r3 = rampartSimulate(createStrategy, 42, 12020);
print('seed42 replay', r1.score, r1.fallTick, r1.hash, 'repeat-identical', r1.hash === r2.hash, 'full', r3.score, r3.hash);
var tot = 0, n = 0, mn = 1e9, mx = 0, t0 = Date.now(), worst = 0;
for (var sd = 90001; sd < 90001 + 200; sd++) { var t1 = Date.now(); var q = rampartSimulate(createStrategy, sd * 7919, 12020); worst = Math.max(worst, Date.now() - t1); tot += q.score; n++; mn = Math.min(mn, q.score); mx = Math.max(mx, q.score); }
print('own seeds', n, 'mean', (tot / n).toFixed(3), 'min', mn, 'max', mx, 'avg ms/game', ((Date.now() - t0) / n).toFixed(1), 'worst ms', worst);

